#include <bits/stdc++.h>using namespace std;class Solution {public:    int jump(vector<int>& arr) {        int n = arr.size();        if(n==1) return 0;        int ans = 0;        int curr = 0;        int mx = 0;        for(int i=0; i<n-1; i++){            mx = max(mx, i + arr[i]);            if(i == curr){                ans++;                curr = mx;                if(curr >= n-1) break;            }        }        return ans;    }};
